{"query":"fragment ProfilePictureRecordFragment on Image {
  height
  url
  width
}

fragment MatchedAuthorStatRecordFragment on Author {
  id
  citationCount
  influentialPaperCount
  paperCount
  primaryFieldOfStudy
  isClaimed
  profilePicture {
    ...ProfilePictureRecordFragment
  }
}

query GetMatchedAuthorStats($authorIds: [Long!]!) {
  authors(authorIds: $authorIds) {
    ...MatchedAuthorStatRecordFragment
  }
}","variables":{"authorIds":[16806116,107924138]},"operationName":"GetMatchedAuthorStats"}
